-- The task dungeon entrances.
--
-- Instance.LoadFromDatabase reads instancexelement for rows whose InstanceID
-- matches the keyname TaskDungeonMission builds -- "TaskDungeon<region>.1" --
-- and a row with ClassType 'entrance' is what sets where the player arrives.
-- We held zero rows, so every task dungeon had no way in.
--
-- 120 entrances, one per task dungeon region: fifteen dungeons of eight
-- regions each, which is how the core's own tables are laid out (a 'long'
-- corridor set and a 'labyrinth' set per dungeon, per realm, per level band).
--
-- These place the door. The creatures behind it are a separate problem.

ON DUPLICATE KEY UPDATE `InstanceID` = `InstanceID`;
